// Minimal TypeScript-like interfaces
type Context = { tenantId: string; userId?: string };
interface Rule { evaluate(ctx: Context): Promise<boolean>; }
type RuleFactory = (cfg?: any) => Rule;
class Registry { private m = new Map<string, RuleFactory>(); register(name, f){ this.m.set(name, f); } create(name, cfg){ const f = this.m.get(name); return f ? f(cfg) : undefined; } }
class TimeWindowRule implements Rule { constructor(start, end){ this.start=start; this.end=end; } async evaluate(ctx){ const t = Date.now()%86400000; return t>=this.start && t<=this.end; } }
class CompositeRule implements Rule { constructor(private rules: Rule[], private op: (a:boolean,b:boolean)=>boolean){ }
  async evaluate(ctx){ let acc = true; for (const r of this.rules){ const v = await r.evaluate(ctx); acc = this.op(acc, v); if(!acc) return false; } return acc; }
}
```

